"""Native-time, one-shot reference reader. No automatic cross-game pose alignment."""
import argparse,base64,hashlib,json
from pathlib import Path
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 p=argparse.ArgumentParser();p.add_argument('--study',type=Path,required=True);a=p.parse_args();data=[]
 for path in sorted((a.study/'captures').glob('*/capture.json')):
  c=json.loads(path.read_text());frames=[]
  for f in c['frames']:
   im=path.parent/f['file']
   if sha(im)!=f['sha256']:raise ValueError('Changed captured pixels')
   frames.append({'url':'data:image/png;base64,'+base64.b64encode(im.read_bytes()).decode(),'duration':f['duration_ms'],'source':f.get('source_index',f.get('source_atlas_id')),'pts':f.get('source_pts_ms',f.get('time_ms'))})
  data.append({'name':path.parent.name,'frames':frames,'size':c['canvas'],'source_url':c['source_url'],'scope':c['scope'],'loop':c.get('loop',False)})
 html='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reference book v18</title><style>body{background:#181a20;color:#eee;font:16px system-ui;margin:18px}button,select,input{font:inherit;margin:5px;max-width:95%}#stage{overflow:auto;background:#272727;border:1px solid #555;height:520px;max-width:100%}#image{display:block;image-rendering:pixelated;max-width:none}p{max-width:1100px;line-height:1.5}#slider{width:300px}a{color:#aaccff}</style><h1>Reference book / เทียบทีละช่วงภาพ</h1><p>Native source clock; external research only. No recovered hidden skeleton, automatic phase alignment or approved original artwork. Container exposures and script-declared timings are labeled separately in the study. Every bounded excerpt plays once and stops; terminal hold has no invented duration.</p><select id="clip"></select><button id="play">Play once</button><button id="prev">Previous</button><button id="next">Next</button><select id="zoom"><option value="1">1× native pixels</option><option value="2">2× inspection</option><option value="4">4× inspection</option></select><input id="slider" type="range"><output id="readout"></output><div id="stage"><img id="image" alt="Current original reference sample"></div><p><a id="source" target="_blank">Original source</a></p><p id="scope"></p><script>const data=DATA;let bank=0,index=0,playing=false,start=0;const sel=document.querySelector('#clip'),slider=document.querySelector('#slider'),img=document.querySelector('#image');data.forEach((b,i)=>{const o=document.createElement('option');o.value=i;o.textContent=b.name;sel.append(o);});function stop(){playing=false;document.querySelector('#play').textContent='Play once';}function show(){const b=data[bank],f=b.frames[index];img.src=f.url;const z=Number(document.querySelector('#zoom').value);img.style.width=b.size[0]*z+'px';img.style.height=b.size[1]*z+'px';slider.max=b.frames.length-1;slider.value=index;document.querySelector('#readout').textContent=`${index+1}/${b.frames.length} · source ${f.source} · PTS ${Number(f.pts).toFixed(3)} ms · ${f.duration===null?'terminal HOLD':f.duration+' ms'}`;document.querySelector('#source').href=b.source_url;document.querySelector('#scope').textContent=b.scope;}sel.onchange=()=>{stop();bank=Number(sel.value);index=0;show();};slider.oninput=()=>{stop();index=Number(slider.value);show();};document.querySelector('#next').onclick=()=>{stop();index=Math.min(data[bank].frames.length-1,index+1);show();};document.querySelector('#prev').onclick=()=>{stop();index=Math.max(0,index-1);show();};document.querySelector('#zoom').onchange=show;document.querySelector('#play').onclick=()=>{if(playing){stop();return;}index=0;start=performance.now();playing=true;document.querySelector('#play').textContent='Pause';show();};function tick(t){if(playing){const f=data[bank].frames[index];if(f.duration===null){stop();}else if(t-start>=f.duration){start+=f.duration;if(index<data[bank].frames.length-1){index++;show();}else{stop();}}}requestAnimationFrame(tick);}show();requestAnimationFrame(tick);</script>'''.replace('DATA',json.dumps(data))
 (a.study/'reference-book.html').write_text(html);print('REFERENCE_BOOK',len(data),'sequences',sum(len(b['frames']) for b in data),'samples')
if __name__=='__main__':main()
